using Domain.Entities.Common;
using Domain.Entities.Enums;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Domain.Entities.BusinessEntities
{
    public class DepositRefund : BaseEntity<int>
    {
        /// Amount that Clinova requested to refund in EGP.
        public decimal RequestedRefundAmount { get; set; }


        public int DepositPaymentId { get; set; }
        public DepositPayment DepositPayment { get; set; } = null!;


        /// Unique key generated by Clinova for this refund operation.
        /// Used to guarantee idempotency inside our system.
        public string IdempotencyKey { get; set; } = null!;


        public DepositRefundReason Reason { get; set; }
        public DepositRefundStatus Status { get; set; }
        public DepositRefundMethodType? MethodType { get; set; } 




        /// <summary>
        /// Paymob transaction ID of the original successful payment.
        /// </summary>
        public string? OriginalTransactionId { get; set; }


        /// <summary>
        /// Paymob refund transaction ID if Paymob provides one.
        /// </summary>
        public string? ProviderRefundTransactionId { get; set; }


        public DateTime RequestedAt { get; set; }

        public DateTime? ProcessedAt { get; set; }

        public string? FailureReason { get; set; }

        public string? ProviderResponse { get; set; }


        // Manual refund evidence
        public string? ManualProofUrl { get; set; }
        public string? ManualTransactionReference { get; set; }



        // Secretary who requested the refund.
        public string? RequestedBySecretaryId { get; set; }
        public Secretary? RequestedBySecretary { get; set; }


        // Secretary who processed the manual refund.
        public string? ProcessedBySecretaryId { get; set; }
        public Secretary? ProcessedBySecretary { get; set; }



        /// <summary>
        /// Used to protect refund state transitions from concurrent requests.
        /// This is important because a payment must never be refunded twice
        /// because of concurrent application requests.
        /// </summary>
        public byte[] RowVersion { get; set; } = null!;
    }
}
